{"code": "import subprocess
import os

# Try to pull the LFS data
try:
    result = subprocess.run(['git', 'lfs', 'pull'], cwd='/app/container', capture_output=True, text=True)
    print("Git LFS pull output:", result.stdout)
    if result.stderr:
        print("Git LFS pull errors:", result.stderr)
    print("Return code:", result.returncode)
except Exception as e:
    print("Error running git lfs pull:", e)"}

